mapper.select:
SELECT /*SQL-ID : isry.couns.constt.unansntabrd.mapper.BbsopcListMapper.selectBbsopcList : (모바일)카카오톡 오픈채팅 게시판목록 답변완료*/ CASE WHEN EE.NUM = 2 THEN EE.BBSCTT_ESNTAL_NO || '-' || EE.RETE_ESNTAL_NO ELSE TO_CHAR(EE.BBSCTT_ESNTAL_NO) END AS BBSCTT_ESNTAL_NO
, CASE WHEN EE.NUM = '2' THEN 'RE: ' || EE.BBSCTT_TTL_NM ELSE EE.BBSCTT_TTL_NM END AS BBSCTT_TTL_NM , C##RG.DEC_B64(EE.WRTR_NM_ENCPT) AS WRTR_NM_ENCPT , C##RG.DEC_B64(EE.CONSTT_NM_ENCPT) AS CONSTT_NM_ENCPT , EE.INDEX_SN AS INDEX_SN , EE.FRST_RGTR_ID AS FRST_RGTR_ID , EE.FRST_REG_DT AS FRST_REG_DT , EE.FRST_REG_DT_ANS_DT , EE.RETE_ESNTAL_NO AS RETE_ESNTAL_NO , EE.NUM AS NUM , COUNT(*) OVER() AS TOTAL_COUNT FROM ( SELECT AA.BBSCTT_CN AS BBSCTT_CN , AA.BBSCTT_ESNTAL_NO AS BBSCTT_ESNTAL_NO , AA.BBSCTT_TTL_NM AS BBSCTT_TTL_NM , AA.FRST_RGTR_ID AS FRST_RGTR_ID , AA.WRTR_NM_ENCPT AS WRTR_NM_ENCPT , TO_CHAR(AA.FRST_REG_DT, 'YYYY-MM-DD') AS FRST_REG_DT , '' AS FRST_REG_DT_ANS_DT , '' AS RETE_ESNTAL_NO , ( SELECT A1.CONSTT_NM_ENCPT FROM AYA150 A1 WHERE 1=1 AND A1.BBSCTT_TYPE_SE_CD = '18' AND A1.BBSCTT_ESNTAL_NO = AA.BBSCTT_ESNTAL_NO ) AS CONSTT_NM_ENCPT , ( SELECT A1.INDEX_SN FROM AYA150 A1 WHERE 1=1 AND A1.BBSCTT_TYPE_SE_CD = '18' AND A1.BBSCTT_ESNTAL_NO = AA.BBSCTT_ESNTAL_NO ) AS INDEX_SN /*상담자배정일련번호*/ , '1' AS NUM FROM AYE100 AA WHERE 1=1
AND AA.FRST_REG_DT >= TO_DATE(#{STARTDATE} || '000000', 'YYYYMMDDHH24MISS') AND AA.FRST_REG_DT < TO_DATE(#{ENDDATE} || '000000', 'YYYYMMDDHH24MISS')+1
AND AA.BBSCTT_TYPE_SE_CD = '18' AND AA.DEL_YN = 'N' AND EXISTS ( SELECT 'Y' FROM AYE120 BB WHERE AA.BBSCTT_ESNTAL_NO = BB.BBSCTT_ESNTAL_NO AND AA.BBSCTT_TYPE_SE_CD = BB.BBSCTT_TYPE_SE_CD AND BB.DEL_YN = 'N' )
AND ( SELECT A1.CONSTT_ID FROM AYA150 A1 WHERE 1=1 AND A1.BBSCTT_TYPE_SE_CD = '18' AND A1.BBSCTT_ESNTAL_NO = AA.BBSCTT_ESNTAL_NO ) = #{LOGIN_ID}
AND AA.BBSCTT_TTL_NM LIKE '%'||#{BBSCTT_TTL_NM}||'%'
AND C##RG.DEC_B64(AA.WRTR_NM_ENCPT) LIKE '%'|| #{WRTR_NM_ENCPT} ||'%'
AND AA.BBSCTT_ESNTAL_NO LIKE '%'||#{BBSCTT_ESNTAL_NO}||'%'
AND AA.PROBM_STTS_LCLAS_SE_CD = #{PROBM_STTS_LCLAS_SE_CD}
AND AA.PROBM_STTS_MLSFC_SE_CD = #{PROBM_STTS_MLSFC_SE_CD}
AND AA.PROBM_STTS_SCLAS_SE_CD = #{PROBM_STTS_SCLAS_SE_CD}
AND AA.PROBM_CAS_LCLAS_SE_CD = #{PROBM_CAS_LCLAS_SE_CD}
AND AA.PROBM_CAS_SCLAS_SE_CD = #{PROBM_CAS_SCLAS_SE_CD}
AND AA.OPEN_CHTT_ETC_CN LIKE '%'|| #{ETC_CN} ||'%'
UNION ALL SELECT BB.RETE_CN AS BBSCTT_CN , BB.BBSCTT_ESNTAL_NO AS BBSCTT_ESNTAL_NO , BB.RETE_TTL_NM AS BBSCTT_TTL_NM , BB.FRST_RGTR_ID AS FRST_RGTR_ID , BB.WRTR_NM_ENCPT AS WRTR_NM_ENCPT , TO_CHAR(AA.FRST_REG_DT, 'YYYY-MM-DD') AS FRST_REG_DT , TO_CHAR(AA.FRST_REG_DT, 'YYYY-MM-DD') || ' / ' || TO_CHAR(BB.FRST_REG_DT, 'YYYY-MM-DD') AS FRST_REG_DT_ANS_DT , BB.RETE_ESNTAL_NO AS RETE_ESNTAL_NO , ( SELECT A1.CONSTT_NM_ENCPT FROM AYA150 A1 WHERE 1=1 AND A1.BBSCTT_TYPE_SE_CD = '18' AND A1.BBSCTT_ESNTAL_NO = BB.RETE_ESNTAL_NO ) AS CONSTT_NM_ENCPT , ( SELECT A1.INDEX_SN FROM AYA150 A1 WHERE 1=1 AND A1.BBSCTT_TYPE_SE_CD = '18' AND A1.BBSCTT_ESNTAL_NO = BB.RETE_ESNTAL_NO ) AS INDEX_SN /*상담자배정일련번호*/ , '2' AS NUM FROM AYE100 AS AA , AYE120 AS BB WHERE 1=1 AND BB.BBSCTT_TYPE_SE_CD = '18' AND BB.BBSCTT_TYPE_SE_CD = AA.BBSCTT_TYPE_SE_CD AND AA.BBSCTT_ESNTAL_NO = BB.BBSCTT_ESNTAL_NO AND BB.DEL_YN = 'N' AND AA.DEL_YN = 'N'
AND ( SELECT A1.CONSTT_ID FROM AYA150 A1 WHERE 1=1 AND A1.BBSCTT_TYPE_SE_CD = '18' AND A1.BBSCTT_ESNTAL_NO = AA.BBSCTT_ESNTAL_NO ) = #{LOGIN_ID}
AND AA.BBSCTT_TTL_NM LIKE '%'||#{BBSCTT_TTL_NM}||'%'
AND C##RG.DEC_B64(BB.WRTR_NM_ENCPT) LIKE '%'|| #{WRTR_NM_ENCPT} ||'%'
AND BB.BBSCTT_ESNTAL_NO LIKE '%'||#{BBSCTT_ESNTAL_NO}||'%'
AND AA.PROBM_STTS_LCLAS_SE_CD = #{PROBM_STTS_LCLAS_SE_CD}
AND AA.PROBM_STTS_MLSFC_SE_CD = #{PROBM_STTS_MLSFC_SE_CD}
AND AA.PROBM_STTS_SCLAS_SE_CD = #{PROBM_STTS_SCLAS_SE_CD}
AND AA.PROBM_CAS_LCLAS_SE_CD = #{PROBM_CAS_LCLAS_SE_CD}
AND AA.PROBM_CAS_SCLAS_SE_CD = #{PROBM_CAS_SCLAS_SE_CD}
AND AA.OPEN_CHTT_ETC_CN LIKE '%'|| #{ETC_CN} ||'%'
AND BB.FRST_REG_DT >= TO_DATE(#{STARTDATE} || '000000', 'YYYYMMDDHH24MISS')
AND BB.FRST_REG_DT < TO_DATE(#{ENDDATE} || '000000', 'YYYYMMDDHH24MISS')+1
) AS EE ORDER BY EE.BBSCTT_ESNTAL_NO DESC , EE.NUM , EE.RETE_ESNTAL_NO DESC , EE.FRST_REG_DT OFFSET #{START_IDX} ROWS FETCH NEXT #{ROW_COUNT} ROWS ONLY

SELECT /*SQL-ID : isry.couns.constt.unansntabrd.mapper.BbsopcListMapper.selectBbsopcList : (모바일)카카오톡 오픈채팅 게시판목록 미답변*/ AA.BBSCTT_CN AS BBSCTT_CN , AA.BBSCTT_ESNTAL_NO AS BBSCTT_ESNTAL_NO , AA.BBSCTT_TTL_NM AS BBSCTT_TTL_NM , AA.FRST_RGTR_ID AS FRST_RGTR_ID , C##RG.DEC_B64(AA.WRTR_NM_ENCPT) AS WRTR_NM_ENCPT , TO_CHAR(AA.FRST_REG_DT, 'YYYY-MM-DD') AS FRST_REG_DT , TO_CHAR(AA.FRST_REG_DT, 'YYYY-MM-DD') AS FRST_REG_DT_ANS_DT , '1' AS NUM , COUNT(*) OVER() AS TOTAL_COUNT , ( SELECT A1.INDEX_SN FROM AYA150 A1 WHERE 1=1 AND A1.BBSCTT_TYPE_SE_CD = '18' AND A1.BBSCTT_ESNTAL_NO = AA.BBSCTT_ESNTAL_NO ) AS INDEX_SN /*상담자배정일련번호*/ , ( SELECT C##RG.DEC_B64(A1.CONSTT_NM_ENCPT) FROM AYA150 A1 WHERE 1=1 AND A1.BBSCTT_TYPE_SE_CD = '18' AND A1.BBSCTT_ESNTAL_NO = AA.BBSCTT_ESNTAL_NO ) AS CONSTT_NM_ENCPT /*상담사*/ FROM AYE100 AS AA WHERE 1=1 AND AA.BBSCTT_TYPE_SE_CD = '18' AND AA.DEL_YN = 'N' AND NOT EXISTS ( SELECT 'Y' FROM AYE120 BB WHERE AA.BBSCTT_ESNTAL_NO = BB.BBSCTT_ESNTAL_NO AND AA.BBSCTT_TYPE_SE_CD = BB.BBSCTT_TYPE_SE_CD AND BB.DEL_YN = 'N' )
AND ( SELECT A1.CONSTT_ID FROM AYA150 A1 WHERE 1=1 AND A1.BBSCTT_TYPE_SE_CD = '18' AND A1.BBSCTT_ESNTAL_NO = AA.BBSCTT_ESNTAL_NO ) = #{LOGIN_ID}
AND AA.BBSCTT_TTL_NM LIKE '%'||#{BBSCTT_TTL_NM}||'%'
AND AA.WRTR_NM_ENCPT = #{WRTR_NM_ENCPT}
AND AA.BBSCTT_ESNTAL_NO LIKE '%'||#{BBSCTT_ESNTAL_NO}||'%'
AND AA.PROBM_STTS_LCLAS_SE_CD = #{PROBM_STTS_LCLAS_SE_CD}
AND AA.PROBM_STTS_MLSFC_SE_CD = #{PROBM_STTS_MLSFC_SE_CD}
AND AA.PROBM_STTS_SCLAS_SE_CD = #{PROBM_STTS_SCLAS_SE_CD}
AND AA.PROBM_CAS_LCLAS_SE_CD = #{PROBM_CAS_LCLAS_SE_CD}
AND AA.PROBM_CAS_SCLAS_SE_CD = #{PROBM_CAS_SCLAS_SE_CD}
AND AA.OPEN_CHTT_ETC_CN LIKE '%'|| #{ETC_CN} ||'%'
AND AA.FRST_REG_DT >= TO_DATE(#{STARTDATE} || '000000', 'YYYYMMDDHH24MISS')
AND AA.FRST_REG_DT < TO_DATE(#{ENDDATE} || '000000', 'YYYYMMDDHH24MISS')+1
ORDER BY BBSCTT_ESNTAL_NO DESC OFFSET #{START_IDX} ROWS FETCH NEXT #{ROW_COUNT} ROWS ONLY

/*SQL-ID : isry.couns.constt.unansntabrd.mapper.BbsopcListMapper.selectBbsopcList : (모바일)카카오톡 오픈채팅 게시판목록 전체*/ SELECT CASE WHEN EE.NUM = 2 THEN EE.BBSCTT_ESNTAL_NO || '-' || EE.RETE_ESNTAL_NO ELSE TO_CHAR(EE.BBSCTT_ESNTAL_NO) END AS BBSCTT_ESNTAL_NO
, CASE WHEN EE.NUM = '2' THEN 'RE: ' || EE.BBSCTT_TTL_NM ELSE EE.BBSCTT_TTL_NM END AS BBSCTT_TTL_NM , C##RG.DEC_B64(EE.WRTR_NM_ENCPT) AS WRTR_NM_ENCPT , C##RG.DEC_B64(EE.CONSTT_NM_ENCPT) AS CONSTT_NM_ENCPT , EE.INDEX_SN AS INDEX_SN , EE.FRST_RGTR_ID AS FRST_RGTR_ID , EE.FRST_REG_DT AS FRST_REG_DT , EE.FRST_REG_DT_ANS_DT , EE.RETE_ESNTAL_NO AS RETE_ESNTAL_NO , EE.NUM AS NUM , COUNT(*) OVER() AS TOTAL_COUNT FROM ( SELECT/*(모바일)카카오톡 오픈채팅 게시판목록 미답변*/ AA.BBSCTT_CN AS BBSCTT_CN , AA.BBSCTT_ESNTAL_NO AS BBSCTT_ESNTAL_NO , AA.BBSCTT_TTL_NM AS BBSCTT_TTL_NM , AA.FRST_RGTR_ID AS FRST_RGTR_ID , AA.WRTR_NM_ENCPT AS WRTR_NM_ENCPT , TO_CHAR(AA.FRST_REG_DT, 'YYYY-MM-DD') AS FRST_REG_DT , TO_CHAR(AA.FRST_REG_DT, 'YYYY-MM-DD') AS FRST_REG_DT_ANS_DT , '' AS RETE_ESNTAL_NO , ( SELECT A1.CONSTT_NM_ENCPT FROM AYA150 A1 WHERE 1=1 AND A1.BBSCTT_TYPE_SE_CD = '18' AND A1.BBSCTT_ESNTAL_NO = AA.BBSCTT_ESNTAL_NO ) AS CONSTT_NM_ENCPT /*상담사*/ , ( SELECT A1.INDEX_SN FROM AYA150 A1 WHERE 1=1 AND A1.BBSCTT_TYPE_SE_CD = '18' AND A1.BBSCTT_ESNTAL_NO = AA.BBSCTT_ESNTAL_NO ) AS INDEX_SN /*상담자배정일련번호*/ , '1' AS NUM FROM AYE100 AS AA WHERE 1=1 AND AA.BBSCTT_TYPE_SE_CD = '18' AND AA.DEL_YN = 'N' AND NOT EXISTS ( SELECT 'Y' FROM AYE120 BB WHERE AA.BBSCTT_ESNTAL_NO = BB.BBSCTT_ESNTAL_NO AND AA.BBSCTT_TYPE_SE_CD = BB.BBSCTT_TYPE_SE_CD AND BB.DEL_YN = 'N' )
AND ( SELECT A1.CONSTT_ID FROM AYA150 A1 WHERE 1=1 AND A1.BBSCTT_TYPE_SE_CD = '18' AND A1.BBSCTT_ESNTAL_NO = AA.BBSCTT_ESNTAL_NO ) = #{LOGIN_ID}
AND AA.BBSCTT_TTL_NM LIKE '%'||#{BBSCTT_TTL_NM}||'%'
AND AA.WRTR_NM_ENCPT = #{WRTR_NM_ENCPT}
AND AA.BBSCTT_ESNTAL_NO LIKE '%'||#{BBSCTT_ESNTAL_NO}||'%'
AND AA.PROBM_STTS_LCLAS_SE_CD = #{PROBM_STTS_LCLAS_SE_CD}
AND AA.PROBM_STTS_MLSFC_SE_CD = #{PROBM_STTS_MLSFC_SE_CD}
AND AA.PROBM_STTS_SCLAS_SE_CD = #{PROBM_STTS_SCLAS_SE_CD}
AND AA.PROBM_CAS_LCLAS_SE_CD = #{PROBM_CAS_LCLAS_SE_CD}
AND AA.PROBM_CAS_SCLAS_SE_CD = #{PROBM_CAS_SCLAS_SE_CD}
AND AA.OPEN_CHTT_ETC_CN LIKE '%'|| #{ETC_CN} ||'%'
AND AA.FRST_REG_DT >= TO_DATE(#{STARTDATE} || '000000', 'YYYYMMDDHH24MISS')
AND AA.FRST_REG_DT < TO_DATE(#{ENDDATE} || '000000', 'YYYYMMDDHH24MISS')+1
UNION ALL SELECT /* 답변이 있는 게시글 */ AA.BBSCTT_CN AS BBSCTT_CN , AA.BBSCTT_ESNTAL_NO AS BBSCTT_ESNTAL_NO , AA.BBSCTT_TTL_NM AS BBSCTT_TTL_NM , AA.FRST_RGTR_ID AS FRST_RGTR_ID , AA.WRTR_NM_ENCPT AS WRTR_NM_ENCPT , TO_CHAR(AA.FRST_REG_DT, 'YYYY-MM-DD') AS FRST_REG_DT , '' AS FRST_REG_DT_ANS_DT , '' AS RETE_ESNTAL_NO , ( SELECT A1.CONSTT_NM_ENCPT FROM AYA150 A1 WHERE 1=1 AND A1.BBSCTT_TYPE_SE_CD = '18' AND A1.BBSCTT_ESNTAL_NO = AA.BBSCTT_ESNTAL_NO ) AS CONSTT_NM_ENCPT , ( SELECT A1.INDEX_SN FROM AYA150 A1 WHERE 1=1 AND A1.BBSCTT_TYPE_SE_CD = '18' AND A1.BBSCTT_ESNTAL_NO = AA.BBSCTT_ESNTAL_NO ) AS INDEX_SN /*상담자배정일련번호*/ , '1' AS NUM FROM AYE100 AA WHERE 1=1 AND AA.BBSCTT_TYPE_SE_CD = '18' AND AA.DEL_YN = 'N' AND EXISTS ( SELECT 'Y' FROM AYE120 BB WHERE AA.BBSCTT_ESNTAL_NO = BB.BBSCTT_ESNTAL_NO AND AA.BBSCTT_TYPE_SE_CD = BB.BBSCTT_TYPE_SE_CD AND BB.DEL_YN = 'N' )
AND ( SELECT A1.CONSTT_ID FROM AYA150 A1 WHERE 1=1 AND A1.BBSCTT_TYPE_SE_CD = '18' AND A1.BBSCTT_ESNTAL_NO = AA.BBSCTT_ESNTAL_NO ) = #{LOGIN_ID}
AND AA.BBSCTT_TTL_NM LIKE '%'||#{BBSCTT_TTL_NM}||'%'
AND AA.WRTR_NM_ENCPT = #{WRTR_NM_ENCPT}
AND AA.BBSCTT_ESNTAL_NO LIKE '%'||#{BBSCTT_ESNTAL_NO}||'%'
AND AA.PROBM_STTS_LCLAS_SE_CD = #{PROBM_STTS_LCLAS_SE_CD}
AND AA.PROBM_STTS_MLSFC_SE_CD = #{PROBM_STTS_MLSFC_SE_CD}
AND AA.PROBM_STTS_SCLAS_SE_CD = #{PROBM_STTS_SCLAS_SE_CD}
AND AA.PROBM_CAS_LCLAS_SE_CD = #{PROBM_CAS_LCLAS_SE_CD}
AND AA.PROBM_CAS_SCLAS_SE_CD = #{PROBM_CAS_SCLAS_SE_CD}
AND AA.OPEN_CHTT_ETC_CN LIKE '%'|| #{ETC_CN} ||'%'
AND AA.FRST_REG_DT >= TO_DATE(#{STARTDATE} || '000000', 'YYYYMMDDHH24MISS')
AND AA.FRST_REG_DT < TO_DATE(#{ENDDATE} || '000000', 'YYYYMMDDHH24MISS')+1
UNION ALL /* 답변 */ SELECT BB.RETE_CN AS BBSCTT_CN , BB.BBSCTT_ESNTAL_NO AS BBSCTT_ESNTAL_NO , BB.RETE_TTL_NM AS BBSCTT_TTL_NM , BB.FRST_RGTR_ID AS FRST_RGTR_ID , BB.WRTR_NM_ENCPT AS WRTR_NM_ENCPT , TO_CHAR(AA.FRST_REG_DT, 'YYYY-MM-DD') AS FRST_REG_DT , TO_CHAR(AA.FRST_REG_DT, 'YYYY-MM-DD') || ' / ' || TO_CHAR(BB.FRST_REG_DT, 'YYYY-MM-DD') AS FRST_REG_DT_ANS_DT , BB.RETE_ESNTAL_NO AS RETE_ESNTAL_NO , ( SELECT A1.CONSTT_NM_ENCPT FROM AYA150 A1 WHERE 1=1 AND A1.BBSCTT_TYPE_SE_CD = '18' AND A1.BBSCTT_ESNTAL_NO = BB.RETE_ESNTAL_NO ) AS CONSTT_NM_ENCPT , ( SELECT A1.INDEX_SN FROM AYA150 A1 WHERE 1=1 AND A1.BBSCTT_TYPE_SE_CD = '18' AND A1.BBSCTT_ESNTAL_NO = BB.RETE_ESNTAL_NO ) AS INDEX_SN /*상담자배정일련번호*/ , '2' AS NUM FROM AYE100 AS AA , AYE120 AS BB WHERE 1=1 AND BB.BBSCTT_TYPE_SE_CD = '18' AND BB.BBSCTT_TYPE_SE_CD = AA.BBSCTT_TYPE_SE_CD AND AA.BBSCTT_ESNTAL_NO = BB.BBSCTT_ESNTAL_NO AND BB.DEL_YN = 'N' AND AA.DEL_YN = 'N'
AND ( SELECT A1.CONSTT_ID FROM AYA150 A1 WHERE 1=1 AND A1.BBSCTT_TYPE_SE_CD = '18' AND A1.BBSCTT_ESNTAL_NO = AA.BBSCTT_ESNTAL_NO ) = #{LOGIN_ID}
AND AA.BBSCTT_TTL_NM LIKE '%'||#{BBSCTT_TTL_NM}||'%'
AND BB.WRTR_NM_ENCPT = #{WRTR_NM_ENCPT}
AND BB.BBSCTT_ESNTAL_NO LIKE '%'||#{BBSCTT_ESNTAL_NO}||'%'
AND AA.PROBM_STTS_LCLAS_SE_CD = #{PROBM_STTS_LCLAS_SE_CD}
AND AA.PROBM_STTS_MLSFC_SE_CD = #{PROBM_STTS_MLSFC_SE_CD}
AND AA.PROBM_STTS_SCLAS_SE_CD = #{PROBM_STTS_SCLAS_SE_CD}
AND AA.PROBM_CAS_LCLAS_SE_CD = #{PROBM_CAS_LCLAS_SE_CD}
AND AA.PROBM_CAS_SCLAS_SE_CD = #{PROBM_CAS_SCLAS_SE_CD}
AND AA.OPEN_CHTT_ETC_CN LIKE '%'|| #{ETC_CN} ||'%'
AND BB.FRST_REG_DT >= TO_DATE(#{STARTDATE} || '000000', 'YYYYMMDDHH24MISS')
AND BB.FRST_REG_DT < TO_DATE(#{ENDDATE} || '000000', 'YYYYMMDDHH24MISS')+1
) AS EE ORDER BY EE.BBSCTT_ESNTAL_NO DESC , EE.NUM , EE.RETE_ESNTAL_NO DESC , EE.FRST_REG_DT OFFSET #{START_IDX} ROWS FETCH NEXT #{ROW_COUNT} ROWS ONLY

mapper.update:
UPDATE AYE100 SET /*SQL-ID : isry.couns.constt.unansntabrd.mapper.BbsopcListMapper.updateBbsopc :  (모바일)카카오톡 오픈채팅 게시판목록 수정*/
            BBSCTT_TTL_NM = #{BBSCTT_TTL_NM}                        /*게시글제목명*/
           ,BBSCTT_CN = #{BBSCTT_CN}                                /*게시글내용*/
           ,LAST_MDFR_ID = #{LAST_MDFR_ID}                    
           ,LAST_MDFCN_DT = SYSDATE        

           ,ATFINO = #{ATFINO}

           ,PROBM_STTS_LCLAS_SE_CD =    #{PROBM_STTS_LCLAS_SE_CD}
           ,PROBM_STTS_MLSFC_SE_CD =    #{PROBM_STTS_MLSFC_SE_CD}
           ,PROBM_STTS_SCLAS_SE_CD =    #{PROBM_STTS_SCLAS_SE_CD}
           ,PROBM_CAS_LCLAS_SE_CD  =    #{PROBM_CAS_LCLAS_SE_CD }
           ,PROBM_CAS_SCLAS_SE_CD  =    #{PROBM_CAS_SCLAS_SE_CD }
           ,OPEN_CHTT_ETC_CN       =    #{ETC_CN      }
WHERE      1=1
    AND     BBSCTT_TYPE_SE_CD = '18'
    AND     BBSCTT_ESNTAL_NO = #{BBSCTT_ESNTAL_NO}

UPDATE AYE120 SET /*SQL-ID : isry.couns.constt.unansntabrd.mapper.BbsopcListMapper.updateBbsopc :  (모바일)카카오톡 오픈채팅 게시판목록 답글수정*/
            RETE_CN = #{RETE_CN}                  
            ,LAST_MDFCN_DT = SYSDATE 
            ,LAST_MDFR_ID = #{LAST_MDFR_ID}

            ,ATFINO = #{ATFINO}

           ,PROBM_STTS_LCLAS_SE_CD =    #{PROBM_STTS_LCLAS_SE_CD}
           ,PROBM_STTS_MLSFC_SE_CD =    #{PROBM_STTS_MLSFC_SE_CD}
           ,PROBM_STTS_SCLAS_SE_CD =    #{PROBM_STTS_SCLAS_SE_CD}
           ,PROBM_CAS_LCLAS_SE_CD  =    #{PROBM_CAS_LCLAS_SE_CD }
           ,PROBM_CAS_SCLAS_SE_CD  =    #{PROBM_CAS_SCLAS_SE_CD }
WHERE       1=1
    AND     BBSCTT_TYPE_SE_CD = '18'
    AND     BBSCTT_ESNTAL_NO = #{BBSCTT_ESNTAL_NO__origin}
    AND     RETE_ESNTAL_NO = #{RETE_ESNTAL_NO__origin}

UPDATE AYE120 SET   /*SQL-ID : isry.couns.constt.unansntabrd.mapper.BbsopcListMapper.deleteBbsopc :  (모바일)카카오톡 오픈채팅 게시판목록 답글삭제*/
              DEL_YN = 'Y'
            , LAST_MDFCN_DT = SYSDATE     
            , LAST_MDFR_ID = #{LAST_MDFR_ID}
WHERE       1=1
    AND     BBSCTT_TYPE_SE_CD = '18'
    AND     BBSCTT_ESNTAL_NO = #{BBSCTT_ESNTAL_NO__origin}
    AND     RETE_ESNTAL_NO = #{RETE_ESNTAL_NO__origin}

UPDATE  /* isry.couns.constt.medscsnntabrd.mapper.BbscttListMapper.updateCrisisBoard : (모바일)카카오톡오픈채팅 위기유형등록 */
        AYA110  
SET
        CRISIS_TYPE_SE_CD       =       #{CRISIS_TYPE_SE_CD} 
    ,   LAST_MDFR_ID            =       #{LAST_MDFR_ID}
    ,   LAST_MDFCN_DT           =       SYSDATE
WHERE   1=1
    AND BBSCTT_ESNTAL_NO       =       #{BBSCTT_ESNTAL_NO}
    AND BBSCTT_TYPE_SE_CD      =       '18'                   /*  게시판유형구분코드  */

UPDATE  /* isry.couns.constt.medscsnntabrd.mapper.BbscttListMapper.updateCrisisPerson : (모바일)카카오톡오픈채팅 위기유형등록 */
        AYA120  
SET
        CRISIS_TYPE_SE_CD       =       #{CRISIS_TYPE_SE_CD}
    ,   CLIENA_ID               =       #{CLIENA_ID}
    ,   LAST_MDFR_ID            =       #{LAST_MDFR_ID}
    ,   LAST_MDFCN_DT           =       SYSDATE
WHERE   1=1
    AND BBSCTT_ESNTAL_NO       =       #{BBSCTT_ESNTAL_NO}
    AND BBSCTT_TYPE_SE_CD      =       '18'                   /*  게시판유형구분코드  */

UPDATE  /* isry.couns.constt.medscsnntabrd.mapper.BbscttListMapper.insertCrisis : (모바일)카카오톡오픈채팅 위기유형등록 */
        AYE100  
SET
        CRISIS_TYPE_SE_CD       =       #{CRISIS_TYPE_SE_CD} 
    ,   LAST_MDFR_ID            =       #{LAST_MDFR_ID}
    ,   LAST_MDFCN_DT           =       SYSDATE
WHERE   1=1
    AND BBSCTT_ESNTAL_NO       =       #{BBSCTT_ESNTAL_NO}
    AND BBSCTT_TYPE_SE_CD      =       '18'                   /*  게시판유형구분코드  */
